import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { STLLoader } from 'three/addons/loaders/STLLoader.js';

const $ = (id) => document.getElementById(id);
const state = {projects:[], projectId:null, project:null, role:null, tree:[], selectedObjectUri:null, selection:null, plan:null, lensCatalog:null, fixationReview:null, dslPreview:null, sessionId:crypto.randomUUID(), activeTab:'view3d', activeDrawingView:null, activeTool:'pointer', tool2d:'pencil', viewerState:'idle', expectedMeshCount:0, renderedTriangles:0, visibleArtifactUris:[], artifactUses:[], drawingProjectionRegions:new Map(), drawingProjectionPromises:new Map(), actionTrace:[], actionSequence:0, lastPointer:null, uiContextQueue:Promise.resolve(), scene:null,camera:null,renderer:null,controls:null,modelRoot:null,meshes:new Map(),highlight:null,drawing:false,path:[],ws:null};
const api = async (url, options={}) => { const response=await fetch(url,options); const text=await response.text(); let data={}; try{data=text?JSON.parse(text):{}}catch{data={detail:text}} if(!response.ok){const problem=data.error||{};const error=new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));error.status=response.status;error.code=problem.code||'HTTP_REQUEST_ERROR';error.correlationId=problem.correlation_id||response.headers.get('X-Correlation-ID');error.registryUri=problem.registry_uri;error.problem=problem;throw error;} return data; };
const jbody=(value)=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
function banner(message,kind='success'){const el=$('banner');el.textContent=message;el.className=`banner ${kind}`;setTimeout(()=>{el.className='banner hidden'},6000)}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function shortUri(uri){const parts=uri.split('/');return parts.slice(-2).join('/');}
const ACTION_TRACE_LIMIT=40;
function diagnosticSafe(value,maxLength=96){return String(value??'').replace(/[|\r\n]/g,' ').replace(/\s+/g,' ').trim().slice(0,maxLength);}
function diagnosticTarget(target){if(!(target instanceof Element))return'unknown';const element=target.closest('button,a,select,input,textarea,.tree-row,canvas')||target;let value=element.tagName.toLowerCase();if(element.classList.contains('tree-row'))value+='.tree-row';if(element.id)value+=`#${element.id}`;else if(element.dataset.tab)value+=`[tab=${element.dataset.tab}]`;else if(element.dataset.tool)value+=`[tool=${element.dataset.tool}]`;else if(element.dataset.view)value+=`[view=${element.dataset.view}]`;else if(element.getAttribute('name'))value+=`[name=${element.getAttribute('name')}]`;const label=element.classList.contains('tree-row')?element.querySelector('span:nth-child(2)')?.textContent:(element.matches('button,a')?element.textContent:'');if(label)value+=`[text=${diagnosticSafe(label,48)}]`;return diagnosticSafe(value,80);}
function diagnosticChange(element){if(!(element instanceof HTMLInputElement||element instanceof HTMLSelectElement||element instanceof HTMLTextAreaElement))return'';if(element instanceof HTMLInputElement&&['checkbox','radio'].includes(element.type))return`checked=${element.checked}`;if(element instanceof HTMLSelectElement||element instanceof HTMLInputElement&&['number','range'].includes(element.type))return`value=${diagnosticSafe(element.value,48)}`;return`text_length=${element.value.length}`;}
function encodeActionArg(action){return[action.seq,action.time.toString(36),action.type,action.target,action.x??'',action.y??'',action.detail].map(value=>diagnosticSafe(value,100)).join('|');}
function decodeActionArg(value){const[seq,time,type,target,x,y,detail='']=String(value).split('|'),parsedSeq=Number(seq),parsedTime=parseInt(time,36),parsedType=diagnosticSafe(type,48),parsedX=x===''?null:Number(x),parsedY=y===''?null:Number(y);if(!Number.isSafeInteger(parsedSeq)||parsedSeq<0||parsedSeq>1e9||!Number.isSafeInteger(parsedTime)||parsedTime<0||parsedTime>8640000000000000||!parsedType)return null;return{seq:parsedSeq,time:parsedTime,type:parsedType,target:diagnosticSafe(target,80),x:Number.isFinite(parsedX)?parsedX:null,y:Number.isFinite(parsedY)?parsedY:null,detail:diagnosticSafe(detail,100)};}
function syncActionUrl(){const url=new URL(location.href);url.searchParams.delete('args');state.actionTrace.forEach(action=>url.searchParams.append('args',encodeActionArg(action)));history.replaceState(null,'',`${url.pathname}${url.search}${url.hash}`);}
function recordUiAction(type,{target='app',x=null,y=null,detail=''}={}){const action={seq:++state.actionSequence,time:Date.now(),type:diagnosticSafe(type,48),target:diagnosticSafe(target,80),x:Number.isFinite(x)?Math.round(x):null,y:Number.isFinite(y)?Math.round(y):null,detail:diagnosticSafe(detail,100)};state.actionTrace.push(action);if(state.actionTrace.length>ACTION_TRACE_LIMIT)state.actionTrace=state.actionTrace.slice(-ACTION_TRACE_LIMIT);syncActionUrl();return action;}
function semanticActionDetail(lastAction,error){if(lastAction==='selection.created'&&state.selection)return diagnosticSafe([`src=${state.selection.source_view}`,`tool=${state.selection.tool}`,`view=${state.activeDrawingView||'3d'}`,`pts=${state.selection.screen_path.length}`,`object=${shortUri(state.selectedObjectUri||'none')}`,`entity=${state.selection.projection_entity_ids[0]||'none'}`].join(';'),100);const parts=[`tab=${state.activeTab}`,`tool=${state.activeTab==='view2d'?state.tool2d:state.activeTool}`];if(state.activeDrawingView)parts.push(`view=${state.activeDrawingView}`);if(state.selectedObjectUri)parts.push(`object=${state.selectedObjectUri}`);if(error)parts.push(`error=${error.code||'ERROR'}:${error.message}`);return diagnosticSafe(parts.join(';'),100);}
function initActionTrace(){const parsed=new URL(location.href).searchParams.getAll('args').map(decodeActionArg).filter(Boolean);state.actionTrace=parsed.slice(-ACTION_TRACE_LIMIT);state.actionSequence=Math.max(0,...state.actionTrace.map(item=>item.seq));document.addEventListener('pointermove',event=>{state.lastPointer={x:event.clientX,y:event.clientY,pageX:event.pageX,pageY:event.pageY};},{capture:true,passive:true});document.addEventListener('pointerdown',event=>{state.lastPointer={x:event.clientX,y:event.clientY,pageX:event.pageX,pageY:event.pageY};},{capture:true,passive:true});document.addEventListener('click',event=>recordUiAction('click',{target:diagnosticTarget(event.target),x:event.clientX,y:event.clientY,detail:`page=${Math.round(event.pageX)},${Math.round(event.pageY)}`}),true);document.addEventListener('change',event=>recordUiAction('change',{target:diagnosticTarget(event.target),x:state.lastPointer?.x,y:state.lastPointer?.y,detail:diagnosticChange(event.target)}),true);document.addEventListener('keydown',event=>{const activationTarget=event.target instanceof Element?event.target.closest('button,a,select,input[type="checkbox"],input[type="radio"]'):null;if(event.key==='Escape'||activationTarget&&['Enter',' '].includes(event.key))recordUiAction('key',{target:diagnosticTarget(event.target),x:state.lastPointer?.x,y:state.lastPointer?.y,detail:`key=${event.key===' '?'Space':event.key}`});},true);syncActionUrl();}
function uiActionDsl(){return state.actionTrace.map(action=>['TWINOBS 1.0','KIND "UiAction"','LEVEL "info"','CODE "UI_ACTION_RECORDED"',`OCCURRED_AT ${JSON.stringify(new Date(action.time).toISOString())}`,`SESSION ${JSON.stringify(state.sessionId)}`,`PROJECT ${JSON.stringify(state.projectId||'unknown')}`,`SEQUENCE ${action.seq}`,`ACTION ${JSON.stringify(action.type)}`,`TARGET ${JSON.stringify(action.target)}`,...(action.x===null?[]:[`POSITION ${JSON.stringify({x:action.x,y:action.y})}`]),...(action.detail?[`DETAILS ${JSON.stringify(action.detail)}`]:[]),'END'].join('\n')).join('\n\n');}
async function writeClipboard(text){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return;}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const copied=document.execCommand('copy');area.remove();if(!copied)throw new Error('Przeglądarka odrzuciła dostęp do schowka');}
async function copyDslLogs(){const button=$('copyDslLogs');button.disabled=true;try{await reportUiContext('logs.copy.requested');const response=await fetch(`/api/v1/projects/${state.projectId}/logs.dsl?limit=300`);if(!response.ok)throw Object.assign(new Error(`Pobranie logów zwróciło HTTP ${response.status}`),{code:'LOG_EXPORT_FAILED'});const serverDsl=await response.text(),content=[uiActionDsl(),serverDsl].filter(Boolean).join('\n\n');await writeClipboard(content);recordUiAction('logs.copied',{target:'button#copyDslLogs',x:state.lastPointer?.x,y:state.lastPointer?.y,detail:`characters=${content.length}`});banner(`Skopiowano logi DSL (${content.length} znaków)`);}catch(error){error.code=error.code||'LOG_EXPORT_FAILED';banner(error.message,'error');await reportUiContext('logs.copy.failed',error);}finally{button.disabled=false;}}
function artifactUrl(artifact){const key=artifact?.uri?.split('/artifact/')[1];return key?`/api/v1/projects/${state.projectId}/artifacts/${encodeURIComponent(key)}`:null;}
function artifactForPath(path){return Object.values(state.project?.artifacts||{}).find(item=>item.path===path);}
async function reportUiContext(lastAction,error=null){if(!state.projectId)return;recordUiAction(lastAction,{target:'app',x:state.lastPointer?.x,y:state.lastPointer?.y,detail:semanticActionDetail(lastAction,error)});const projectId=state.projectId,payload={session_id:state.sessionId,project_id:projectId,route:`${location.pathname}${location.search}`,active_tab:state.activeTab,selected_object_uri:state.selectedObjectUri,selection_uri:state.selection?.uri||null,active_tool:state.activeTab==='view2d'?state.tool2d:state.activeTool,viewer_state:state.viewerState,loaded_mesh_count:state.meshes.size,expected_mesh_count:state.expectedMeshCount,rendered_triangles:state.renderedTriangles,visible_artifact_uris:[...state.visibleArtifactUris],artifacts:state.artifactUses.map(item=>({...item})),last_action:lastAction,error_code:error?.code||null,error_message:error?.message||null};state.uiContextQueue=state.uiContextQueue.then(async()=>{try{const response=await fetch(`/api/v1/projects/${projectId}/ui-context`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)console.warn('UI context report rejected',response.status);}catch(reportError){console.warn('UI context report failed',reportError);}});return state.uiContextQueue;}

async function init(){initActionTrace();initTabs();initViewer();initSelectionCanvas();bindActions();await loadProjects();}
async function loadProjects(){state.projects=await api('/api/v1/projects');const select=$('projectSelect');select.innerHTML=state.projects.map(p=>`<option value="${esc(p.project_id)}">${esc(p.name)} · ${esc(p.revision)}</option>`).join('');if(!state.projects.length){banner('Brak dostępnych projektów','error');return;}state.projectId=select.value||state.projects[0].project_id;await loadProject();}
async function loadProject(){const payload=await api(`/api/v1/projects/${state.projectId}`);state.project=payload.project;state.role=payload.role;$('roleBadge').textContent=state.role;$('exportLink').href=`/api/v1/projects/${state.projectId}/export`;$('downloadDrawingsPdf').href=`/api/v1/projects/${state.projectId}/drawings.pdf`;const treePayload=await api(`/api/v1/projects/${state.projectId}/tree`);state.tree=treePayload.tree;await loadFeatureLenses();renderTree();renderSpec();renderLifecycle();renderFixationHistory();ensureDslTemplate();renderEvolutionHistory();await loadModels();loadDrawings();connectWs();await reportUiContext('project.loaded');}
function connectWs(){if(state.ws)state.ws.close();const protocol=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(`${protocol}://${location.host}/ws/projects/${state.projectId}`);state.ws.onmessage=async(event)=>{const msg=JSON.parse(event.data);if(msg.events){await refreshSnapshot(false)}};}
async function refreshSnapshot(show=true){const payload=await api(`/api/v1/projects/${state.projectId}`);state.project=payload.project;const treePayload=await api(`/api/v1/projects/${state.projectId}/tree`);state.tree=treePayload.tree;renderTree();renderSpec();renderLifecycle();renderFixationHistory();renderEvolutionHistory();if(show)banner('Projekt odświeżony');}
function initTabs(){document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{state.activeTab=btn.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===btn));document.querySelectorAll('.tab-page').forEach(x=>x.classList.toggle('active',x.id===btn.dataset.tab));if(btn.dataset.tab==='view3d')resizeViewer();if(btn.dataset.tab==='view2d')resize2dCanvases();reportUiContext('tab.changed');}));}
function renderTree(){const root=$('objectTree');root.innerHTML='';state.tree.forEach(n=>root.appendChild(treeNode(n)));if(state.selectedObjectUri)renderObjectInspector(state.project.objects[state.selectedObjectUri]);}
function treeNode(container){const wrap=document.createElement('div');wrap.className='tree-node';const row=document.createElement('div');row.className='tree-row'+(container.object.uri===state.selectedObjectUri?' selected':'');const children=container.children||[];row.innerHTML=`<span class="tree-caret">${children.length?'▾':'·'}</span><span>${esc(container.object.name)}</span><span class="kind-pill">${esc(container.object.kind)}</span><span class="visibility" title="Pokaż/ukryj">◉</span>`;row.addEventListener('click',()=>selectObject(container.object.uri));row.querySelector('.visibility').addEventListener('click',(event)=>{event.stopPropagation();toggleObjectVisibility(container.object.uri,event.currentTarget)});wrap.appendChild(row);const childWrap=document.createElement('div');children.forEach(ch=>childWrap.appendChild(treeNode(ch)));wrap.appendChild(childWrap);return wrap;}
function selectObject(uri,action='object.selected'){state.selectedObjectUri=uri;state.fixationReview=null;renderTree();renderObjectInspector(state.project.objects[uri]);const mesh=state.meshes.get(uri);if(mesh){state.meshes.forEach(m=>m.material.emissive?.setHex(0x000000));mesh.material.emissive?.setHex(0x18395f);}updateSelectionSummary();renderLensCatalog();renderFixationHistory();reportUiContext(action);}
function toggleObjectVisibility(uri,button){const mesh=state.meshes.get(uri);if(mesh){mesh.visible=!mesh.visible;button.textContent=mesh.visible?'◉':'○';}}
function renderObjectInspector(node){if(!node){$('objectInspector').innerHTML='<div class="empty">Brak danych.</div>';return;}const params=Object.entries(node.parameters||{}).map(([k,v])=>`<div class="kv"><span>${esc(k)}</span><span>${esc(v.value)} ${esc(v.unit||'')}</span></div>`).join('');const features=(node.features||[]).map(f=>`<div class="feature-card"><b>${esc(f.name)}</b><div>${esc(f.feature_type)}</div><small>${esc(shortUri(f.uri))}</small></div>`).join('');$('objectInspector').innerHTML=`<div class="object-title">${esc(node.name)}</div><div class="hint">${esc(node.uri)}</div><div class="kv"><span>process</span><span>${esc(node.manufacturing?.process)}</span></div><div class="kv"><span>make/buy</span><span>${esc(node.manufacturing?.make_buy)}</span></div><div class="kv"><span>print</span><span>${node.inclusion?.print_job?'yes':'no'}</span></div>${params}<h3 style="margin-top:10px">Cechy</h3>${features||'<div class="empty">Brak cech.</div>'}`;}

function initViewer(){const host=$('viewer3d');const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(42,1,.1,5000);camera.up.set(0,0,1);camera.position.set(150,-175,115);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.outputColorSpace=THREE.SRGBColorSpace;host.insertBefore(renderer.domElement,$('selectionCanvas3d'));const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(40,45,18);scene.add(new THREE.HemisphereLight(0xffffff,0x243447,2.2));const light=new THREE.DirectionalLight(0xffffff,2.3);light.position.set(150,-100,180);scene.add(light);const fill=new THREE.DirectionalLight(0x9bc4ff,1.0);fill.position.set(-100,120,80);scene.add(fill);const grid=new THREE.GridHelper(260,26,0x5d718d,0x314157);grid.rotation.x=Math.PI/2;scene.add(grid);const root=new THREE.Group();scene.add(root);Object.assign(state,{scene,camera,renderer,controls,modelRoot:root});new ResizeObserver(resizeViewer).observe(host);(function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)})();}
function resizeViewer(){if(!state.renderer)return;const host=$('viewer3d');const w=host.clientWidth,h=host.clientHeight;state.renderer.setSize(w,h,false);state.camera.aspect=w/h;state.camera.updateProjectionMatrix();resizeCanvas($('selectionCanvas3d'));}
function resizeCanvas(canvas){const rect=canvas.getBoundingClientRect();const ratio=devicePixelRatio||1;canvas.width=Math.max(1,Math.round(rect.width*ratio));canvas.height=Math.max(1,Math.round(rect.height*ratio));const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);}
async function loadModels(){const host=$('viewer3d'),status=$('viewerStatus');state.modelRoot.clear();state.meshes.clear();state.renderedTriangles=0;state.visibleArtifactUris=[];state.viewerState='loading';host.dataset.viewerState='loading';host.dataset.loadedMeshes='0';host.dataset.renderedTriangles='0';status.textContent='Ładowanie modelu…';status.style.display='grid';const loader=new STLLoader();const nodes=Object.values(state.project.objects).filter(n=>n.metadata?.viewer_mesh);state.expectedMeshCount=nodes.length;state.artifactUses=nodes.map(node=>{const artifact=artifactForPath(node.metadata.viewer_mesh);return{uri:artifact?.uri||node.metadata.viewer_mesh,path:node.metadata.viewer_mesh,purpose:`viewer3d:${node.uri}`,status:'loading'};});const failures=[];for(const [index,node] of nodes.entries()){const artifact=artifactForPath(node.metadata.viewer_mesh),use=state.artifactUses[index],url=artifactUrl(artifact)||'/'+node.metadata.viewer_mesh;try{const geometry=await loader.loadAsync(url);geometry.computeVertexNormals();const material=new THREE.MeshStandardMaterial({color:index?0xd6dbe4:0x8995a7,roughness:.66,metalness:.02,transparent:true,opacity:1});const mesh=new THREE.Mesh(geometry,material);mesh.name=node.uri;mesh.userData.objectUri=node.uri;mesh.userData.artifactUri=artifact?.uri||null;state.modelRoot.add(mesh);state.meshes.set(node.uri,mesh);state.renderedTriangles+=Math.floor((geometry.attributes.position?.count||0)/3);use.status='visible';if(artifact?.uri)state.visibleArtifactUris.push(artifact.uri);}catch(error){use.status='failed';use.error_code='UI_ARTIFACT_LOAD_FAILED';failures.push(error);console.error(error);}}host.dataset.loadedMeshes=String(state.meshes.size);host.dataset.expectedMeshes=String(state.expectedMeshCount);host.dataset.renderedTriangles=String(state.renderedTriangles);if(nodes.length>0&&state.meshes.size===nodes.length){state.viewerState='ready';status.style.display='none';fitCamera();}else{state.viewerState=state.meshes.size?'partial':'error';status.textContent=nodes.length?`Nie udało się wczytać ${nodes.length-state.meshes.size} z ${nodes.length} brył.`:'Projekt nie wskazuje modeli 3D.';status.style.display='grid';}host.dataset.viewerState=state.viewerState;const error=failures.length?Object.assign(new Error(`${failures.length} artefaktów 3D nie zostało załadowanych`),{code:'UI_ARTIFACT_LOAD_FAILED'}):null;if(error)banner(`${error.message}. Szczegóły: ${error.code}`,'error');await reportUiContext('viewer3d.models.loaded',error);}
function fitCamera(){const box=new THREE.Box3().setFromObject(state.modelRoot);if(box.isEmpty())return;const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),d=Math.max(size.x,size.y,size.z)*2.1;state.camera.position.set(center.x+d*.75,center.y-d,center.z+d*.72);state.controls.target.copy(center);state.camera.near=Math.max(.1,d/200);state.camera.far=d*15;state.camera.updateProjectionMatrix();state.controls.update();}

function initSelectionCanvas(){const canvas=$('selectionCanvas3d');['pointerdown','pointermove','pointerup'].forEach(type=>canvas.addEventListener(type,e=>handleDraw(e,'3d')));}
function bindDrawingCanvas(canvas){['pointerdown','pointermove','pointerup'].forEach(type=>canvas.addEventListener(type,e=>handleDraw(e,'2d')));canvas.classList.add('drawing');new ResizeObserver(()=>resizeCanvas(canvas)).observe(canvas.parentElement);}
function activateTool(tool,dimension='3d'){if(dimension==='3d'){state.activeTool=tool;document.querySelectorAll('.tool[data-tool]').forEach(b=>{if(!b.classList.contains('tool2d'))b.classList.toggle('active',b.dataset.tool===tool)});const canvas=$('selectionCanvas3d');canvas.classList.toggle('drawing',tool!=='pointer');state.controls.enabled=tool==='pointer';}else{state.tool2d=tool;document.querySelectorAll('.tool2d').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));document.querySelectorAll('.drawing-canvas').forEach(canvas=>canvas.classList.add('drawing'));}reportUiContext('tool.changed');}
function handleDraw(event,dimension){const tool=dimension==='3d'?state.activeTool:state.tool2d;const canvas=dimension==='3d'?$('selectionCanvas3d'):event.currentTarget;const rect=canvas.getBoundingClientRect();const point={x:event.clientX-rect.left,y:event.clientY-rect.top};if(dimension==='3d'&&tool==='pointer'&&event.type==='pointerdown'){createPointerSelection(point);return;}if(event.type==='pointerdown'){if(dimension==='2d'){state.activeDrawingView=canvas.dataset.view;document.querySelectorAll('.drawing-card').forEach(card=>card.classList.toggle('active',card.dataset.view===state.activeDrawingView));}state.drawing=true;state.path=[point];canvas.setPointerCapture(event.pointerId);drawOverlay(canvas,state.path,tool);return;}if(event.type==='pointermove'&&state.drawing){if(tool==='rectangle')state.path=[state.path[0],point];else state.path.push(point);drawOverlay(canvas,state.path,tool);return;}if(event.type==='pointerup'&&state.drawing){state.drawing=false;if(tool==='rectangle'){const a=state.path[0],b=point;state.path=[a,{x:b.x,y:a.y},b,{x:a.x,y:b.y},a];}else if(tool==='lasso'&&state.path.length>2)state.path.push(state.path[0]);drawOverlay(canvas,state.path,tool);if(dimension==='3d')createAreaSelection(state.path,tool);else create2dSelection(state.path,tool,state.activeDrawingView,canvas);}}
function drawOverlay(canvas,path,tool){const ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect();ctx.clearRect(0,0,rect.width,rect.height);if(!path.length)return;ctx.lineWidth=2;ctx.strokeStyle='#fb7185';ctx.fillStyle='rgba(96,165,250,.14)';ctx.setLineDash(tool==='pencil'?[]:[7,4]);ctx.beginPath();ctx.moveTo(path[0].x,path[0].y);path.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.stroke();if(tool!=='pencil'&&path.length>2){ctx.closePath();ctx.fill();}}
function raycast(point){const rect=state.renderer.domElement.getBoundingClientRect();const mouse=new THREE.Vector2((point.x/rect.width)*2-1,-(point.y/rect.height)*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(mouse,state.camera);return ray.intersectObjects([...state.meshes.values()].filter(m=>m.visible),false);}
function semanticFace(objectUri,normal){const base=objectUri;const ax=Math.abs(normal.x),ay=Math.abs(normal.y),az=Math.abs(normal.z);let name='surface';if(az>=ax&&az>=ay)name=normal.z>0?'top':'bottom';else if(ay>=ax)name=normal.y>0?'rear':'front';else name=normal.x>0?'right':'left';return `${base}/face/${name}`;}
function hitData(hit){const normal=hit.face?.normal?.clone()||new THREE.Vector3();normal.transformDirection(hit.object.matrixWorld);return{object_uri:hit.object.userData.objectUri,mesh_hash:null,face_index:hit.faceIndex,semantic_face_uri:semanticFace(hit.object.userData.objectUri,normal),brep_face_id:null,point:{x:hit.point.x,y:hit.point.y,z:hit.point.z},normal:{x:normal.x,y:normal.y,z:normal.z},distance:hit.distance};}
function createPointerSelection(point){const hits=raycast(point);if(!hits.length){clearSelection();return;}const hit=hitData(hits[0]);selectObject(hit.object_uri);state.selection=makeSelection('3d','pointer',[point],[hit]);renderHighlight([hit]);updateSelectionSummary();drawOverlay($('selectionCanvas3d'),[point,{x:point.x+1,y:point.y+1}],'pencil');reportUiContext('selection.created');}
function createAreaSelection(path,tool){const samples=sampleSelection(path,tool);const unique=new Map();for(const p of samples){const hit=raycast(p)[0];if(hit){const data=hitData(hit);unique.set(`${data.object_uri}:${data.face_index}`,data);if(unique.size>350)break;}}const hits=[...unique.values()];if(!hits.length){banner('Zaznaczenie nie przecięło bryły','error');return;}const targets=[...new Set(hits.map(h=>h.object_uri))];state.selectedObjectUri=targets[0];state.selection=makeSelection('3d',tool,path,hits,targets);renderHighlight(hits);renderTree();renderObjectInspector(state.project.objects[targets[0]]);updateSelectionSummary();reportUiContext('selection.created');}
function sampleSelection(path,tool){const points=[...path];for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],distance=Math.hypot(b.x-a.x,b.y-a.y),n=Math.min(30,Math.ceil(distance/12));for(let j=1;j<n;j++)points.push({x:a.x+(b.x-a.x)*j/n,y:a.y+(b.y-a.y)*j/n});}if(tool!=='pencil'&&path.length>3){const xs=path.map(p=>p.x),ys=path.map(p=>p.y);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);for(let x=minX;x<=maxX;x+=18)for(let y=minY;y<=maxY;y+=18)if(pointInPolygon({x,y},path))points.push({x,y});}return points;}
function pointInPolygon(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if(((a.y>p.y)!=(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y||1e-9)+a.x))inside=!inside;}return inside;}
function makeSelection(source,tool,path,hits=[],targets=null){const id=crypto.randomUUID(),root=`poa://${state.project.tenant}/${state.project.project_id}@${state.project.revision}`;const points=hits.map(h=>h.point);let aabb=null;if(points.length)aabb={minimum:{x:Math.min(...points.map(p=>p.x)),y:Math.min(...points.map(p=>p.y)),z:Math.min(...points.map(p=>p.z))},maximum:{x:Math.max(...points.map(p=>p.x)),y:Math.max(...points.map(p=>p.y)),z:Math.max(...points.map(p=>p.z))}};const camera=source==='3d'?{projection:'perspective',position:v3(state.camera.position),target:v3(state.controls.target),up:v3(state.camera.up),fov:state.camera.fov,zoom:state.camera.zoom,viewport_width:state.renderer.domElement.clientWidth,viewport_height:state.renderer.domElement.clientHeight}:null;return{selection_id:id,uri:`${root}/region/${id}`,project_id:state.projectId,project_revision:state.project.revision,source_view:source,tool,target_object_uris:targets||[state.selectedObjectUri].filter(Boolean),screen_path:path,ray_hits:hits,world_aabb:aabb,camera,source_artifact_uri:null,projection_entity_ids:[],notes:'',created_by:'browser-user'};}
function v3(v){return{x:v.x,y:v.y,z:v.z}}
function renderHighlight(hits){if(state.highlight){state.scene.remove(state.highlight);state.highlight.geometry.dispose();state.highlight.material.dispose();}const positions=[];hits.slice(0,500).forEach(h=>positions.push(h.point.x,h.point.y,h.point.z));const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));const material=new THREE.PointsMaterial({size:1.8,color:0xff537a,sizeAttenuation:true,depthTest:false});state.highlight=new THREE.Points(geometry,material);state.highlight.renderOrder=100;state.scene.add(state.highlight);}
function clearSelection(){state.selection=null;state.plan=null;$('planContent').innerHTML='Plan pojawi się tutaj.';$('planContent').className='plan-content empty';$('applyButton').disabled=true;[$('selectionCanvas3d'),...document.querySelectorAll('.drawing-canvas')].forEach(c=>{const ctx=c.getContext('2d');ctx.clearRect(0,0,c.clientWidth,c.clientHeight)});if(state.highlight){state.scene.remove(state.highlight);state.highlight=null;}updateSelectionSummary();reportUiContext('selection.cleared');}
function updateSelectionSummary(){const el=$('selectionSummary');if(!state.selection){el.className='empty';el.innerHTML='Zaznacz obszar w 3D lub 2D.';return;}el.className='';const s=state.selection,projection=s.projection_entity_ids.length?`<div class="kv"><span>projekcja</span><span>${s.projection_entity_ids.map(esc).join(', ')}</span></div>`:'';el.innerHTML=`<div class="kv"><span>źródło</span><span>${esc(s.source_view)}</span></div><div class="kv"><span>narzędzie</span><span>${esc(s.tool)}</span></div><div class="kv"><span>trafienia</span><span>${s.ray_hits.length}</span></div>${projection}<div>${s.target_object_uris.map(u=>`<span class="selection-chip">${esc(shortUri(u))}</span>`).join('')}</div><div class="hint">${esc(s.uri)}</div>`;}

function resize2dCanvases(){document.querySelectorAll('.drawing-canvas').forEach(resizeCanvas);}
function drawingViewLabel(view){return({front:'Front',top:'Top',side:'Side'}[view]||view.replaceAll('_',' ').replace(/^./,letter=>letter.toUpperCase()));}
function polygonSelectionBbox(element){const values=String(element.getAttribute('points')||'').trim().split(/[ ,]+/).map(Number);if(values.length<6||values.length%2||!values.every(Number.isFinite))return null;const xs=values.filter((_,index)=>index%2===0),ys=values.filter((_,index)=>index%2===1);return[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)];}
async function loadDrawingProjectionRegions(view,artifact){const baseUrl=artifactUrl(artifact)||'/'+artifact.path,url=`${baseUrl}${baseUrl.includes('?')?'&':'?'}projection-regions=2`,projection=Object.values(state.project.projection_maps||{}).find(item=>item.source_artifact_uri===artifact.uri);try{const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const documentSvg=new DOMParser().parseFromString(await response.text(),'image/svg+xml'),svg=documentSvg.documentElement,viewBox=String(svg.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number);if(viewBox.length!==4||!viewBox.every(Number.isFinite)||viewBox[2]<=0||viewBox[3]<=0)throw new Error('SVG viewBox missing');let source='svg-metadata',regions=[...svg.querySelectorAll('[data-projection-entity][data-selection-bbox]')].map(element=>{const bbox=String(element.getAttribute('data-selection-bbox')||'').split(/[ ,]+/).map(Number);return{entityId:element.getAttribute('data-projection-entity'),bbox};}).filter(item=>item.entityId&&item.bbox.length===4&&item.bbox.every(Number.isFinite)&&item.bbox[2]>item.bbox[0]&&item.bbox[3]>item.bbox[1]&&projection?.entities?.[item.entityId]);if(!regions.length&&projection){const entityIds=Object.keys(projection.entities||{}),polygons=[...svg.querySelectorAll('#VISIBLE_EDGES polygon')];if(entityIds.length===polygons.length){source='polygon-order-fallback';regions=polygons.map((element,index)=>({entityId:entityIds[index],bbox:polygonSelectionBbox(element)})).filter(item=>item.bbox);}}if(regions.length){state.drawingProjectionRegions.set(view,{artifactUri:artifact.uri,viewBox,regions});recordUiAction('viewer2d.projection.ready',{target:`canvas[view=${view}]`,detail:`regions=${regions.length};source=${source}`});}else if(projection)recordUiAction('viewer2d.projection.unavailable',{target:`canvas[view=${view}]`,detail:`artifact=${shortUri(artifact.uri)};reason=no_regions`});}catch(error){console.warn('Projection regions unavailable',view,error);if(projection)recordUiAction('viewer2d.projection.unavailable',{target:`canvas[view=${view}]`,detail:`artifact=${shortUri(artifact.uri)};error=${error.message}`});}}
function inferDrawingProjection(path,view,canvas){const source=state.drawingProjectionRegions.get(view);if(!source||!path.length||!canvas.clientWidth||!canvas.clientHeight)return null;const xs=path.map(point=>point.x),ys=path.map(point=>point.y),centerX=(Math.min(...xs)+Math.max(...xs))/2,centerY=(Math.min(...ys)+Math.max(...ys))/2,[minX,minY,width,height]=source.viewBox,x=minX+centerX/canvas.clientWidth*width,y=minY+centerY/canvas.clientHeight*height;const region=source.regions.filter(item=>{const[x1,y1,x2,y2]=item.bbox;return x>=x1&&x<=x2&&y>=y1&&y<=y2;}).sort((left,right)=>(left.bbox[2]-left.bbox[0])*(left.bbox[3]-left.bbox[1])-(right.bbox[2]-right.bbox[0])*(right.bbox[3]-right.bbox[1]))[0];if(!region)return null;const projection=Object.values(state.project.projection_maps||{}).find(item=>item.source_artifact_uri===source.artifactUri&&item.entities?.[region.entityId]),binding=projection?.entities?.[region.entityId];return binding?{entityId:region.entityId,objectUri:binding.object_uri}:null;}
function loadDrawings(){if(!state.project)return;const host=$('drawingList'),entries=Object.entries(state.project.metadata.default_2d_views||{}).map(([view,uri])=>({view,artifact:state.project.artifacts[uri]})).filter(item=>item.artifact);host.innerHTML='';state.drawingProjectionRegions.clear();state.drawingProjectionPromises.clear();$('drawingCount').textContent=`${entries.length} ${entries.length===1?'rzut':'rzuty'} · wszystkie w jednym widoku`;state.activeDrawingView=entries[0]?.view||null;if(!entries.length){host.innerHTML='<div class="empty">Projekt nie zawiera rzutów 2D.</div>';return;}entries.forEach(({view,artifact},index)=>{const purpose=`viewer2d:${view}`,card=document.createElement('article');card.className=`drawing-card${index===0?' active':''}`;card.dataset.view=view;card.innerHTML=`<header class="drawing-card-header"><div><h3>${esc(drawingViewLabel(view))}</h3><small>${esc(artifact.name)} · ${esc(artifact.uri)}</small></div><a class="button secondary" href="${esc(artifactUrl(artifact)||'/'+artifact.path)}" download>Pobierz SVG</a></header><div class="drawing-sheet"><img alt="Rzut ${esc(drawingViewLabel(view))}" /><canvas class="selection-overlay drawing-canvas" data-view="${esc(view)}" aria-label="Zaznaczenie na rzucie ${esc(drawingViewLabel(view))}"></canvas></div>`;host.appendChild(card);const image=card.querySelector('img'),canvas=card.querySelector('canvas');bindDrawingCanvas(canvas);state.drawingProjectionPromises.set(view,loadDrawingProjectionRegions(view,artifact));image.onload=()=>{if(!state.artifactUses.some(item=>item.uri===artifact.uri&&item.purpose===purpose))state.artifactUses.push({uri:artifact.uri,path:artifact.path,purpose,status:'visible'});if(!state.visibleArtifactUris.includes(artifact.uri))state.visibleArtifactUris.push(artifact.uri);resizeCanvas(canvas);reportUiContext('viewer2d.artifact.loaded');};image.onerror=()=>{const error=Object.assign(new Error(`Nie udało się wczytać rysunku ${artifact.name}`),{code:'UI_ARTIFACT_LOAD_FAILED'});state.artifactUses.push({uri:artifact.uri,path:artifact.path,purpose,status:'failed',error_code:error.code});reportUiContext('viewer2d.artifact.failed',error);banner(error.message,'error');};image.src=artifactUrl(artifact)||'/'+artifact.path;});}
async function create2dSelection(path,tool,view,canvas){await state.drawingProjectionPromises.get(view);const inferred=inferDrawingProjection(path,view,canvas),target=inferred?.objectUri||state.selectedObjectUri;if(!target){drawOverlay(canvas,[],'pencil');const error=Object.assign(new Error('Nie można ustalić obiektu dla tego obszaru; wybierz go w drzewie'),{code:'UI_SELECTION_TARGET_REQUIRED'});banner(error.message,'error');reportUiContext('selection.rejected',error);return;}state.selection=makeSelection('2d',tool,path,[],[target]);const artifactUri=state.project.metadata.default_2d_views?.[view];state.selection.source_artifact_uri=artifactUri||null;if(inferred?.objectUri===target)state.selection.projection_entity_ids=[inferred.entityId];state.selection.notes=`drawing_view=${view}${inferred?`;projection_entity=${inferred.entityId}`:''}`;if(state.selectedObjectUri!==target)selectObject(target,'object.inferred');else updateSelectionSummary();reportUiContext('selection.created');}

async function saveAnnotation(){if(!state.selection){banner('Brak zaznaczenia','error');return;}const text=$('annotationText').value.trim();if(!text){banner('Wpisz uwagę','error');return;}await api(`/api/v1/projects/${state.projectId}/annotations`,jbody({text,selection:state.selection}));$('annotationText').value='';banner('Uwaga została zapisana');}
async function planChange(){if(!state.selection){banner('Brak zaznaczenia','error');return;}const prompt=$('changePrompt').value.trim();if(!prompt){banner('Wpisz opis zmiany','error');return;}$('planButton').disabled=true;try{const mapping=await api(`/api/v1/projects/${state.projectId}/selections/resolve`,jbody(state.selection));state.selectionMap=mapping;const result=await api(`/api/v1/projects/${state.projectId}/change-plans`,jbody({prompt,selection:state.selection}));state.plan=result.plan;$('plannerMode').textContent=`selection=${mapping.status}; ${result.mode}: ${result.message}`;renderPlan(result.plan);$('applyButton').disabled=false;const blockers=(mapping.diagnostics||[]).filter(x=>x.severity==='blocking').length;banner(blockers?'Plan zapisany, ale mapowanie zawiera blokery — sprawdź pytania.':'Zaznaczenie rozwiązane, a plan sprawdzony pod kątem zakresu',blockers?'error':'success');}catch(error){banner(error.message,'error')}finally{$('planButton').disabled=false;}}
function renderPlan(plan){const ops=plan.operations.map(op=>`<div class="plan-op"><b>${esc(op.kind)}</b><code>${esc(op.target_uri)}</code><div>${esc(op.rationale)}</div><pre>${esc(JSON.stringify(op.arguments,null,2))}</pre></div>`).join('');$('planContent').className='plan-content';$('planContent').innerHTML=`<div class="kv"><span>plan</span><span>${esc(plan.plan_id)}</span></div>${ops}${plan.unresolved_questions?.length?`<h3>Pytania</h3><ul>${plan.unresolved_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}`;}
async function applyPlan(){if(!state.plan)return;try{const result=await api(`/api/v1/projects/${state.projectId}/change-plans/${state.plan.plan_id}/apply`,{method:'POST'});$('applyButton').disabled=true;banner(`Zastosowano ${result.result.parameter_patches.length} bezpiecznych patchy; odroczono ${result.result.deferred_operations.length} operacji CAD.`);await refreshSnapshot(false);}catch(error){banner(error.message,'error')}}

function renderSpec(){const p=state.project;const objects=Object.values(p.objects);const yes=v=>v?'✓':'—';const rows=objects.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.kind)}</td><td>${esc(n.manufacturing?.make_buy)}</td><td>${esc(n.manufacturing?.process)}</td><td>${yes(n.inclusion?.print_job)}</td><td>${yes(n.inclusion?.cnc_job)}</td><td>${yes(n.inclusion?.purchase_order)}</td><td>${yes(n.inclusion?.pcb_fabrication)}</td><td>${yes(n.inclusion?.software_release)}</td><td>${yes(n.inclusion?.reference_only)}</td></tr>`).join('');const features=objects.flatMap(n=>(n.features||[]).map(f=>`<tr><td>${esc(n.name)}</td><td>${esc(f.name)}</td><td>${esc(f.feature_type)}</td><td>${esc(Object.entries(f.parameters||{}).map(([k,v])=>`${k}=${v.value}${v.unit||''}`).join(', '))}</td><td>${esc((f.semantic_faces||[]).map(shortUri).join(', '))}</td></tr>`)).join('');const artifacts=Object.values(p.artifacts).map(a=>{const key=a.uri.split('/artifact/')[1];const url=key?`/api/v1/projects/${state.projectId}/artifacts/${encodeURIComponent(key)}`:'#';return`<tr><td><a href="${url}">${esc(a.name)}</a></td><td>${esc(a.kind)}</td><td>${esc(shortUri(a.object_uri||''))}</td><td>${a.source?'source':'generated/reference'}</td><td>${esc(a.sha256?String(a.sha256).slice(0,12):'—')}</td></tr>`}).join('');$('specContent').innerHTML=`<section class="data-section"><h3>Obiekty / xBOM</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Obiekt</th><th>Typ</th><th>Make/Buy</th><th>Proces</th><th>3D print</th><th>CNC</th><th>Buy</th><th>PCB</th><th>Software</th><th>Reference</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="data-section"><h3>Cechy i wymiary</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Obiekt</th><th>Cecha</th><th>Typ</th><th>Parametry</th><th>Semantic faces</th></tr></thead><tbody>${features}</tbody></table></div></section><section class="data-section"><h3>Artefakty do pobrania</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Nazwa</th><th>Typ</th><th>Obiekt</th><th>Pochodzenie</th><th>SHA-256</th></tr></thead><tbody>${artifacts}</tbody></table></div></section>`;}
function renderLifecycle(){
  const p=state.project;
  const blueprints=Object.values(p.lifecycle_blueprints||{});
  const blueprintRows=blueprints.map(b=>`<tr><td>${esc(b.name||b.blueprint_id)}</td><td><code>${esc(b.blueprint_id)}</code></td><td>${esc(b.current_stage)}</td><td>${b.stages?.length||0}</td><td>${b.transitions?.length||0}</td><td>${b.tailored?'yes':'no'}</td></tr>`).join('');
  const history=[...(p.lifecycle_history||[])].sort((a,b)=>String(b.occurred_at||'').localeCompare(String(a.occurred_at||''))).map(h=>`<tr><td>${esc(h.occurred_at||'')}</td><td><code>${esc(h.blueprint_id)}</code></td><td>${esc(h.from_stage)} → ${esc(h.to_stage)}</td><td>${esc(h.status)}</td><td>${esc(h.approved_by||'—')}</td><td>${esc((h.unmet_criteria||[]).join('; ')||h.rationale||'—')}</td></tr>`).join('');
  const gates=(p.lifecycle_gates||[]).map(g=>`<tr><td>${esc(g.stage)}</td><td>${esc(g.status)}</td><td>${esc(g.exit_criteria.join('; '))}</td><td>${esc(g.approver_roles.join(', '))}</td></tr>`).join('');
  const failures=(p.failure_modes||[]).map(f=>{const r=f.severity*f.occurrence*f.detection;return`<tr><td>${esc(shortUri(f.target_uri))}</td><td>${esc(f.failure)}</td><td>${esc(f.effect)}</td><td class="${r>200?'rpn-high':r>100?'rpn-medium':'rpn-low'}">${r}</td></tr>`}).join('');
  const tests=Object.values(p.test_plans||{}).flatMap(plan=>(plan.cases||[]).map(t=>`<tr><td>${esc(plan.name)}</td><td>${esc(t.name)}</td><td>${esc(t.test_type)}</td><td>${esc(t.lifecycle_stage)}</td><td>${esc(t.status)}</td><td>${esc(t.execution_adapter)}</td></tr>`)).join('');
  const scenarios=(p.human_scenarios||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.actor)}</td><td>${esc(x.stage)}</td><td>${x.steps.length}</td></tr>`).join('');
  $('lifecycleContent').innerHTML=`
    <section class="data-section"><h3>Blueprinty lifecycle</h3><p class="hint">Aktualny etap projektu: <b>${esc(p.lifecycle_stage||'—')}</b></p><div class="table-wrap"><table class="data-table"><thead><tr><th>Nazwa</th><th>ID</th><th>Etap bieżący</th><th>Etapy</th><th>Przejścia</th><th>Tailored</th></tr></thead><tbody>${blueprintRows||'<tr><td colspan="6">Brak blueprintów zapisanych przez DSL.</td></tr>'}</tbody></table></div></section>
    <section class="data-section"><h3>Historia przejść</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Czas</th><th>Blueprint</th><th>Przejście</th><th>Status</th><th>Akceptacja</th><th>Evidence / blokery</th></tr></thead><tbody>${history||'<tr><td colspan="6">Brak przejść lifecycle.</td></tr>'}</tbody></table></div></section>
    <section class="data-section"><h3>Legacy gates / bramki projektu</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Etap</th><th>Status</th><th>Exit criteria</th><th>Role</th></tr></thead><tbody>${gates}</tbody></table></div></section>
    <section class="data-section"><h3>Plany testów</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Plan</th><th>Test</th><th>Typ</th><th>Etap</th><th>Status</th><th>Adapter</th></tr></thead><tbody>${tests}</tbody></table></div></section>
    <section class="data-section"><h3>Scenariusze obsługi przez człowieka</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Scenariusz</th><th>Aktor</th><th>Etap</th><th>Kroki</th></tr></thead><tbody>${scenarios}</tbody></table></div></section>
    <section class="data-section"><h3>FMEA / słabe punkty</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Cel</th><th>Uszkodzenie</th><th>Skutek</th><th>RPN</th></tr></thead><tbody>${failures}</tbody></table></div></section>`;
}
async function loadFeatureLenses(){if(!state.lensCatalog)state.lensCatalog=await api('/api/v1/feature-lenses?include_disabled=true');renderLensCatalog();}
function filteredLenses(){if(!state.lensCatalog)return[];const category=$('lensCategory')?.value||'';return state.lensCatalog.lenses.filter(l=>l.enabled&&(!category||l.category===category));}
function renderLensCatalog(){if(!state.lensCatalog||!$('lensCatalog'))return;const visible=filteredLenses();const sourceGap=state.lensCatalog.lenses.filter(l=>!l.enabled).length;const target=state.selectedObjectUri?shortUri(state.selectedObjectUri):'nie wybrano';$('lensCatalogSummary').textContent=`${state.lensCatalog.active_lens_count} aktywnych soczewek, ${sourceGap} jawna luka źródłowa; cel: ${target}.`;$('lensCatalog').innerHTML=visible.map(l=>`<div class="lens-row"><strong>${l.order}. ${esc(l.name)}</strong><small>${esc(l.category)} · ${esc(l.summary)}</small></div>`).join('')||'<div class="empty">Brak soczewek w tej kategorii.</div>';}
async function runFixation(){if(!state.selectedObjectUri){banner('Wybierz obiekt w drzewie przed przeglądem','error');return;}const button=$('fixationButton');button.disabled=true;$('fixationOutput').innerHTML='<div class="empty">Analiza soczewek…</div>';try{const lenses=filteredLenses().map(l=>l.id);const result=await api(`/api/v1/projects/${state.projectId}/design-fixation/scan`,jbody({target_uri:state.selectedObjectUri,challenge:$('fixationChallenge').value.trim(),lens_ids:lenses,max_alternatives:Number($('fixationMax').value||8),use_llm:$('fixationLlm').checked,record:true}));state.fixationReview=result.review;renderFixationReview(result.review,result.mode,result.message);banner(`Przegląd zapisany: ${result.review.alternatives.length} alternatyw`);await refreshSnapshot(false);}catch(error){$('fixationOutput').textContent=error.message;banner(error.message,'error')}finally{button.disabled=false;}}
function renderFixationHistory(){if(state.fixationReview)return;const reviews=Object.values(state.project?.design_fixation_reviews||{}).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));if(reviews.length)renderFixationReview(reviews.at(-1),'recorded','Ostatni zapisany przegląd.');else if($('fixationOutput'))$('fixationOutput').innerHTML='<div class="empty">Nie uruchomiono przeglądu.</div>';renderLensCatalog();}
function renderFixationReview(review,mode='recorded',message=''){if(!$('fixationOutput'))return;const pct=Math.round((review.coverage_ratio||0)*100);const observations=(review.observations||[]).map(o=>{const lens=state.lensCatalog?.lenses.find(l=>l.id===o.lens_id);return`<tr><td>${esc(lens?.name||o.lens_id)}</td><td class="status-${esc(o.status)}">${esc(o.status)}</td><td>${esc(o.note)}</td></tr>`}).join('');const ideas=(review.alternatives||[]).map(i=>`<article class="idea-card"><h4>${esc(i.title)}</h4><div class="lens-tags">${i.lens_ids.map(id=>`<span class="lens-tag">${esc(id)}</span>`).join('')}</div><p>${esc(i.summary)}</p>${i.proposed_changes?.length?`<b>Propozycje</b><ul>${i.proposed_changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${i.risks?.length?`<b>Ryzyka</b><ul>${i.risks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<div class="hint">źródło: ${esc(i.source)} · confidence ${Math.round((i.confidence||0)*100)}%</div></article>`).join('');$('fixationOutput').innerHTML=`<div class="coverage"><b>${pct}% pokrycia</b><div class="coverage-meter"><span style="width:${pct}%"></span></div><span>${review.observed_count}/${review.applicable_count}</span></div><p class="hint">${esc(mode)} · ${esc(message)} · ${esc(review.target_uri)}</p><h3>Alternatywy</h3>${ideas||'<div class="empty">Brak alternatyw.</div>'}<details><summary>Macierz obserwacji (${review.observations.length})</summary><div class="table-wrap"><table class="data-table observation-table"><thead><tr><th>Soczewka</th><th>Status</th><th>Uzasadnienie</th></tr></thead><tbody>${observations}</tbody></table></div></details>${review.warnings?.length?`<details><summary>Uwagi źródłowe</summary><ul>${review.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}`;}


function defaultTwinScript(){const target=state.selectedObjectUri||Object.keys(state.project?.objects||{}).find(uri=>uri.endsWith('/part/base'))||`poa://demo/${state.projectId||'demo-rpi5'}@main/part/base`;const revision=state.project?.revision||'main';return `TWINSCRIPT 1.0
NAME "${state.project?.name||'Product'} evolution"
NAMESPACE product
LABEL workflow=design-evolution

PROJECT ${state.projectId||'demo-rpi5'} REVISION ${revision}
FOCUS "${target}"

GOAL VERB improve OBJECT "selected product region" \\
  OUTCOME "better function, manufacturability and lifecycle evidence without assuming the current form is fixed"
PRESERVE "approved interfaces and safety constraints"
AVOID "changes outside the selected POA scope"
ASSUME "the current implementation is one candidate, not the goal itself"

METHODS goal_ladder,object_decomposition,bidirectional_graph,feature_lenses,adjacent_possible,brainswarm,assumption_reversal,mutation,recombination,experiment
SEED_VERBS improve,simplify,manufacture,inspect
LENSES parts,material,shape,size,connectivity_among_parts,spatial_relations_among_parts,force_characteristics,durability_characteristics,human_use,causal_relations,aesthetics
DIMENSIONS manufacturability,assemblability,serviceability,testability,reliability,reversibility,experiment_cost,adjacent_possible
LENS_OPTIONS SOURCE true EXTENSIONS true ASSUMPTIONS true MAX 96
RESOURCE_OPTIONS DESCENDANTS true FEATURES true PARAMETERS true MATERIALS true PROCESSES true ARTIFACTS true REQUIREMENTS true EVIDENCE true MAX 250
SEARCH UP 1 DOWN 2 SIDEWAYS 1 MAX 40 OPPOSITES true

EVOLVE POPULATION 12 GENERATIONS 3 OFFSPRING 2 MUTATION 0.8 CROSSOVER 0.3 SEED 17
OPERATOR reframe_goal WEIGHT 1.0
OPERATOR repurpose_feature WEIGHT 1.0
OPERATOR parameter_shift WEIGHT 0.8
OPERATOR make_reversible WEIGHT 0.8
OPERATOR adjacent_association WEIGHT 1.0
OPERATOR crossover WEIGHT 0.4
SELECT_TOP 5
MIN_SCORE 0.25

LIFECYCLE hardware-product START detailed_design TARGET verification APPROVAL true
GATE experiment CHECK "shortlisted concepts have recorded experiments" ROLE creator,admin BLOCKING true
VERIFY "build or simulate the shortlisted concept"
VERIFY "record evidence against preserved constraints"
REALIZE change_plan DRY_RUN true APPROVAL true MAX_PLANS 3
OUTPUT GRAPHS json,dot,mermaid REPORTS json,markdown,csv
PERSIST_ARTIFACTS true
INCLUDE_CHANGE_PLANS true
NOTE "Generated candidates are hypotheses and require verification."
END
`;}
function ensureDslTemplate(force=false){const editor=$('dslSource');if(!editor)return;if(force||!editor.value.trim())editor.value=defaultTwinScript();}
function dslDiagnosticsHtml(items=[]){return `<div class="dsl-diagnostics">${items.map(d=>`<div class="dsl-diagnostic ${esc(d.severity)}"><b>${esc(d.severity)} · ${esc(d.code)}</b><div>${esc(d.message)}</div>${d.path?`<small>${esc(d.path)}</small>`:''}</div>`).join('')||'<div class="hint">Brak diagnostyki.</div>'}</div>`;}
function renderDslCompilation(payload){state.dslPreview=payload;const out=$('dslOutput');if(!out)return;const run=payload.evolution_run;const selected=new Set(run?.selected_candidate_ids||[]);const candidates=(run?.candidates||[]).filter(c=>selected.has(c.candidate_id)).map(c=>`<article class="candidate-card"><h4>${esc(c.title)}</h4><div class="candidate-score">score ${Number(c.overall_score||0).toFixed(3)} · generation ${esc(c.generation)}</div><p>${esc(c.summary)}</p><div class="lens-tags">${(c.lens_ids||[]).slice(0,10).map(x=>`<span class="lens-tag">${esc(x)}</span>`).join('')}</div>${c.validation_steps?.length?`<details><summary>Walidacja</summary><ul>${c.validation_steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}</article>`).join('');const plans=(payload.change_plans||[]).map(p=>`<li><code>${esc(p.plan_id)}</code> — ${p.operations?.length||0} operacji, status ${esc(p.status)}</li>`).join('');const blueprint=payload.lifecycle_blueprint;out.className='';out.innerHTML=`<div class="dsl-summary"><b>${payload.valid?'Program poprawny':'Program zablokowany'}</b>${payload.execution?`<div class="hint">execution: ${esc(payload.execution.execution_id)} · ${esc(payload.execution.status)}</div>`:''}${run?`<div class="coverage"><b>${run.goal_variants.length} wariantów celu</b><span>${run.resources.length} zasobów · ${run.candidates.length} kandydatów · ${run.selected_candidate_ids.length} shortlist</span></div>`:''}${blueprint?`<p>Lifecycle: <code>${esc(blueprint.blueprint_id)}</code>, current ${esc(blueprint.current_stage)} → target ${esc(payload.document?.spec?.lifecycle?.target_stage||'configured stages')}</p>`:''}${plans?`<h3>Typed ChangePlans</h3><ul class="dsl-plan-list">${plans}</ul>`:''}${payload.artifact_keys?`<p class="hint">Artefakty: ${esc(Object.keys(payload.artifact_keys).join(', '))}</p>`:''}</div>${dslDiagnosticsHtml(payload.diagnostics||[])}${run?`<div class="dsl-summary"><h3>Shortlista ewolucji</h3>${candidates||'<div class="empty">Brak kandydatów spełniających próg.</div>'}</div>`:''}`;}
async function previewDsl(){const button=$('dslPreviewButton');button.disabled=true;$('dslOutput').innerHTML='<div class="empty">Kompilowanie grafu celu, zasobów i wariantów…</div>';try{const payload=await api(`/api/v1/projects/${state.projectId}/dsl/preview`,jbody({source:$('dslSource').value,source_format:$('dslFormat').value}));renderDslCompilation(payload);banner(payload.valid?'Podgląd ewolucji gotowy':'DSL wymaga korekty',payload.valid?'success':'error');}catch(error){$('dslOutput').textContent=error.message;banner(error.message,'error')}finally{button.disabled=false;}}
async function applyDsl(){if(!$('dslCommit').checked){banner('Zaznacz potwierdzenie zapisu zdarzeń','error');return;}const button=$('dslApplyButton');button.disabled=true;try{const payload=await api(`/api/v1/projects/${state.projectId}/dsl/apply`,jbody({source:$('dslSource').value,source_format:$('dslFormat').value,dry_run:false,generate_artifacts:true}));renderDslCompilation(payload);await refreshSnapshot(false);banner(`Zapisano ${payload.events?.length||0} zdarzeń i artefakty ewolucji`);}catch(error){banner(error.message,'error')}finally{$('dslCommit').checked=false;button.disabled=true;}}
function renderEvolutionHistory(){const host=$('evolutionHistory');if(!host||!state.project)return;const runs=Object.values(state.project.evolution_runs||{}).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));const executions=Object.values(state.project.dsl_executions||state.project.dsl_programs||{}).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));const blueprints=Object.values(state.project.lifecycle_blueprints||{});host.innerHTML=`<h3>Historia projektu</h3><div class="hint">${runs.length} runów · ${executions.length} wykonań DSL · ${blueprints.length} blueprintów lifecycle</div>${runs.slice(0,8).map(r=>`<div class="history-item"><b>${esc(r.program?.metadata?.name||r.run_id)}</b><div><code>${esc(r.run_id)}</code> · ${r.candidates?.length||0} kandydatów · ${r.selected_candidate_ids?.length||0} shortlist</div></div>`).join('')||'<div class="empty">Brak zapisanych runów.</div>'}`;}

async function runSimulation(type){const out=$('simulationOutput');out.textContent='Uruchamianie…';try{let result;if(type==='power')result=await api(`/api/v1/projects/${state.projectId}/simulations/power`,{method:'POST'});if(type==='thermal'){const rpi=Object.keys(state.project.objects).find(u=>u.includes('raspberry-pi-5'));const enclosure=Object.keys(state.project.objects).find(u=>u.endsWith('/assembly/enclosure'));result=await api(`/api/v1/projects/${state.projectId}/simulations/thermal`,jbody({power_by_uri_w:{[rpi]:10,[enclosure]:1.5},duration_s:600,sample_every_s:30}));}if(type==='human')result=await api(`/api/v1/projects/${state.projectId}/simulations/human`);if(type==='mechanical')result=await api(`/api/v1/projects/${state.projectId}/checks/mechanical`);out.textContent=JSON.stringify(result,null,2);}catch(error){out.textContent=error.message;}}
async function invite(){const email=$('inviteEmail').value.trim();if(!email){banner('Wpisz email','error');return;}try{const result=await api('/api/v1/access-requests',jbody({project_id:state.projectId,requested_email:email,requested_role:$('inviteRole').value,message:'Access requested from the project web UI.'}));$('inviteStatus').textContent=`Wysłano do decydenta: ${result.approver_email}`;banner('Wniosek o dostęp zapisany');}catch(error){banner(error.message,'error')}}

function bindActions(){$('projectSelect').addEventListener('change',async e=>{state.projectId=e.target.value;clearSelection();await loadProject()});$('copyDslLogs').addEventListener('click',copyDslLogs);$('refreshButton').addEventListener('click',()=>refreshSnapshot());document.querySelectorAll('.tool[data-tool]').forEach(b=>{if(!b.classList.contains('tool2d'))b.addEventListener('click',()=>activateTool(b.dataset.tool,'3d'))});document.querySelectorAll('.tool2d').forEach(b=>b.addEventListener('click',()=>activateTool(b.dataset.tool,'2d')));$('clearSelection').addEventListener('click',clearSelection);$('clearSelection2d').addEventListener('click',clearSelection);$('fitCamera').addEventListener('click',fitCamera);$('xrayToggle').addEventListener('change',e=>state.meshes.forEach(m=>{m.material.opacity=e.target.checked?.45:1;m.material.depthWrite=!e.target.checked}));$('saveAnnotation').addEventListener('click',saveAnnotation);$('planButton').addEventListener('click',planChange);$('applyButton').addEventListener('click',applyPlan);$('powerButton').addEventListener('click',()=>runSimulation('power'));$('thermalButton').addEventListener('click',()=>runSimulation('thermal'));$('humanButton').addEventListener('click',()=>runSimulation('human'));$('mechanicalButton').addEventListener('click',()=>runSimulation('mechanical'));$('fixationButton').addEventListener('click',runFixation);$('lensCategory').addEventListener('change',renderLensCatalog);$('dslTemplateButton').addEventListener('click',()=>ensureDslTemplate(true));$('dslPreviewButton').addEventListener('click',previewDsl);$('dslCommit').addEventListener('change',e=>$('dslApplyButton').disabled=!e.target.checked);$('dslApplyButton').addEventListener('click',applyDsl);$('inviteButton').addEventListener('click',invite);}
init().catch(error=>{banner(`${error.message}${error.code?` (${error.code})`:''}`,'error');reportUiContext('application.init.failed',error);});
